from pathlib import Path
import json,hashlib
r=Path(__file__).resolve().parents[1];root=r.parents[1];b=r/'build/motion-more';b.mkdir(exist_ok=True)
spec={
'S09r':'Locked medium shot. The girl in peach gently offers one steaming bun in her mittened hands to the blue whale-hood young man. He leans toward the bun with a small warm smile. The two-tone-coat young woman behind adjusts the tiny bun-shaped hat once. Understated real human acting, no talking, no text, no new people.',
'S22r':'Locked wide golden-hour shot, all six full bodies and shoes remain visible. The tall cream-haired terracotta-cardigan man at center takes ONE small weighted step forward: heel lands then knee softly settles. The other five watch without walking. Natural human movement, warm realistic skin, no new people, no camera move.',
'S26r':'Locked high crane view. All fifteen friends on the wet crossing gather into a crouch in a gentle canon from front row to back row. Feet remain planted, knees bend and arms sweep back in anticipation of a jump. No jump yet. Preserve the count and costumes, no camera move, no cut, no text.',
'S28r':'Cinematic anime upward tracking shot through the gold ring helix. The six small friends step and spring upward from one horizontal glowing ring to the next, moving through cloud layers toward dawn. Camera rises with them. Preserve character identities, readable stepping contact and distinct separated bodies, no extra characters, no text. Golden sunrise emerges above clouds.',
'S29r':'The central girl and young man rotate together in zero gravity without releasing their one joined pair of hands. Only a gentle quarter-turn; hair and cardigan float. Keep ALL FOUR central shoes and every head in frame. The other four tiny friends drift, black-white-jacket man stays deadpan. Camera gently rolls 15 degrees. Preserve cel linework and dawn colors, no extra bodies or text.'}
jobs=[]
for sid,prompt in spec.items():jobs.append({'id':'m_'+sid,'shot_id':sid,'image_key':sid,'image':f'episodes/landing-day-one/assets/{sid}.png','endpoint':'i2v','duration':4,'resolution':'768P','prompt_expansion_mode':'disabled','prompt':prompt,'out':f'episodes/landing-day-one/assets/m_{sid}.mp4'})
def write(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2))
def bind(p):return {'path':str(p.relative_to(root)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
write(b/'story.json',{'shots':[{'id':j['shot_id'],'asset':j['image_key']} for j in jobs]});write(b/'assets.json',{j['image_key']:j['image'] for j in jobs})
evidence=['Three photoreal people, peach mittened girl and blue whale-hood man adjacent; bun presentation can be finished with authored prop if generated action lacks it.','Six real humans share a visible plaza and all shoes fit frame; center terracotta figure can step without leaving camera view.','Six crouched foreground leads and nine distinct colored background figures occupy one wet crossing; camera is overhead.','Six tiny cel friends occupy different gold ring levels among clouds; each ring is a visible support surface.','Repaired wide flight source preserves linked hands and all four central shoes plus four supporting friends, with sky margin below.']
review={'schema_version':1,'status':'approved','reviewer':'Codex static image inspection','story':bind(b/'story.json'),'assets':bind(b/'assets.json'),'additional_inputs':[bind(r/'shots.md'),bind(r/'cast-and-world.md')],'sources':[bind(root/j['image']) for j in jobs],'cuts':[],'notes':'Independently staged source frames, all inspected. This record approves source framing only; generated action and final edit remain separate reviews.'}
for i,(j,k) in enumerate(zip(jobs,jobs[1:])):review['cuts'].append({'from_shot':j['shot_id'],'to_shot':k['shot_id'],'from_asset':j['image_key'],'to_asset':k['image_key'],'relation':'intentional_discontinuity','status':'approved','evidence':evidence[i]+' Next: '+evidence[i+1],'issues':[]})
write(b/'continuity.json',review);write(b/'manifest.json',{'continuity_review':str((b/'continuity.json').relative_to(root)),'jobs':jobs});print('5 clips, $0.60 estimate')
